const b = $('Webhook Pulido').first().json.body;
const ctx = $json;
const conv = (ctx.conversacion||[]).slice(-30).map((t,i)=>`[${i+1}] (etapa: ${t.etapa||'?'}${t.bloqueado?', BLOQUEADO':''})
Lead: ${t.lead||''}
Bot: ${t.bot||''}${t.razon?('
(router: '+t.razon+')'):''}`).join('

') || '(sin turnos)';
const etapas = (ctx.etapas||[]).map(e=>`### ETAPA id:${e.id} | ${e.nombre} (calif ${e.calificacion})
Objetivo: ${e.objetivo||''}
Reglas:
${e.reglas||''}`).join('

');
const guard = (ctx.guardrails||[]).map(g=>`- ${g.nombre}: ${g.regla}`).join('
');
const ag = ctx.agente||{};
const pc = (ctx.patrones_causa||[]).map(p=>`${p.causa}: ${p.n}`).join(', ') || 'ninguno';
const pe = (ctx.patrones_etapa||[]).map(p=>`${p.etapa}: ${p.n}`).join(', ') || 'ninguno';
const prev = (ctx.casos_previos||[]).map((k,i)=>`(${i+1}) [${k.estado}] causa=${k.causa} etapa=${k.etapa||'-'} :: feedback: ${k.feedback} :: fix: ${k.propuesto||''}`).join('
') || '(sin casos previos)';
const sys = `Sos un OPTIMIZADOR EXPERTO de agentes de ventas conversacionales por WhatsApp (universidades). Razoná a fondo y paso a paso.

Recibís: (A) CONVERSACIÓN real (con la etapa de cada respuesta), (B) FEEDBACK del analista, (C) CONFIG del agente (etapas+reglas, guardrails, persona/tono), (D) flags pausado/transbordado, (E) MEMORIA: patrones históricos y casos previos de este agente.

TAREA:
1) Diagnosticá la CAUSA RAÍZ (qué etapa/regla la originó). Si es 'no responde', mirá pausado/transbordado/bloqueo.
2) Mirá la MEMORIA: si este problema YA apareció antes (patrón recurrente), marcá es_patron=true, estimá frecuencia, y proponé un fix MÁS SISTÉMICO (no un parche puntual).
3) Proponé UN cambio CONCRETO y MÍNIMO que no rompa lo que funciona. Preferí ajustar las REGLAS de la etapa responsable.

Devolvé SOLO JSON válido: {"diagnostico":"...","causa":"no_responde|muy_agresivo|salto_de_etapa|poco_consultivo|alucinacion|tono|otro","es_patron":true|false,"frecuencia":<int>,"etapa_id":"<id o null>","etapa_nombre":"...","campo":"reglas|objetivo|persona|tono|guardrail_nuevo|config","accion":"append|replace|insert","texto_actual":"<fragmento exacto o ''>","texto_propuesto":"<el cambio>","justificacion":"...","conclusion":"si es patrón, qué recomendás a nivel sistema","riesgo":"bajo|medio|alto"}`;
const usr = `FEEDBACK:
${b.feedback}

FLAGS: pausado=${ctx.pausado}, transbordado=${ctx.transbordado}

=== MEMORIA (este agente) ===
Patrones por causa: ${pc}
Patrones por etapa: ${pe}
Casos previos:
${prev}

=== CONVERSACIÓN ===
${conv}

=== CONFIG ===
Persona: ${ag.persona} | Tono: ${ag.tono}
GUARDRAILS:
${guard}
ETAPAS:
${etapas}`;
return [{ json: { payload: { model:'o4-mini', response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}] } } }];

const raw = $json.choices?.[0]?.message?.content || '{}';
let p; try { p = JSON.parse(raw); } catch(e){ p = { error:'no_parse', raw }; }
if (p.etapa_id && !/^[0-9a-f]{8}-[0-9a-f]{4}-/i.test(String(p.etapa_id))) p.etapa_id = null;
if (typeof p.frecuencia !== 'number') p.frecuencia = 1;
return [{ json: p }];
